CREATE TABLE `Posts` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `content` text,
  `category` enum('news','reviews','brands','cars') NOT NULL,
  `image1` longblob,
  `image2` longblob,
  `image3` longblob,
  `image4` longblob,
  `brand_intro` text,
  `brand_history` text,
  `brand_philosophy` text,
  `review_intro` text,
  `review_driving` text,
  `review_design` text,
  `car_years` varchar(255) DEFAULT NULL,
  `car_bodytype` varchar(255) DEFAULT NULL,
  `car_engines` varchar(255) DEFAULT NULL,
  `news_text` text,
  `userId` int DEFAULT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `userId` (`userId`),
  CONSTRAINT `posts_ibfk_1` FOREIGN KEY (`userId`) REFERENCES `Users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
